const availablePlay=play;
play=function(id){if(id!==1)return;reader.classList.add('summer-story');readingMenu.classList.add('summer-menu');naming.classList.add('summer-menu');availablePlay(id)};
stories[1].description='Ты приехала к морю, чтобы снова услышать себя. Но на чужой премьере узнаёшь собственную историю.';
const collectionRender=render;
render=function(){collectionRender();document.querySelectorAll('[data-play]').forEach(button=>{if(Number(button.dataset.play)!==1){button.disabled=true;button.setAttribute('aria-label','В разработке');if(!button.classList.contains('card-open'))button.textContent='В разработке';}});document.querySelectorAll('.card').forEach(card=>{const button=card.querySelector('[data-play]');if(button&&Number(button.dataset.play)!==1){card.classList.add('in-development');card.querySelector('.cover-label').textContent='В разработке';card.querySelector('.card-meta span').textContent='Скоро в библиотеке';}})};
const hero=document.querySelector('.hero');hero.querySelector('[data-play]').dataset.play='1';hero.querySelector('[data-play]').disabled=false;hero.querySelector('[data-play]').removeAttribute('aria-label');hero.querySelector('h2').innerHTML='Не <em>случайные</em>';hero.querySelector('p').textContent='Месяц у моря. Чужой ключ. История, которой пора вернуть твоё имя.';hero.querySelector('.hero-tags').textContent='ИТАЛИЯ · МЕДЛЕННОЕ СБЛИЖЕНИЕ';hero.querySelector('img').alt='Залитый солнцем балкон над итальянским побережьем';hero.querySelector('.hero-label span:last-child').textContent='СЕРИЯ ПЕРВАЯ';hero.querySelector('img').src='assets/backgrounds/summer-03-hd.jpg';
const finale=document.createElement('dialog');finale.id='summer-finale';finale.setAttribute('aria-labelledby','finale-title');document.body.append(finale);
function showSummerFinale(){const r=state.runs[1];finale.innerHTML=`<div class="finale-postcard"><div class="finale-view"><div class="finale-caption"><p>Не случайные</p><span>Лето, которое останется с тобой</span></div></div><section class="finale-letter"><div class="finale-lemon" aria-hidden="true"></div><p class="finale-kicker">Серия первая завершена</p><h2 id="finale-title">Своим<br><em>именем</em></h2><p class="finale-note">Море осталось за окнами.<br>Твоя история только начинается.</p><div class="finale-stats" aria-label="Итоги серии">${[['trust','Близость','❦'],['truth','Честность','✧'],['boundary','Опора на себя','❧']].map(([key,label,symbol])=>`<div class="finale-stat"><span class="stat-emblem" aria-hidden="true">${symbol}</span><span class="stat-label">${label}</span><span class="stat-value" aria-label="Всего ${r[key]||0}">${r[key]||0}</span><span class="stat-gain" aria-label="За серию плюс ${r[key]||0}">(+${r[key]||0})</span></div>`).join('')}<p class="stat-legend">Всего · в скобках — за эту серию</p></div><div class="finale-actions"><button id="episode-replay">Пройти серию заново</button><button id="episode-home">На главный экран</button></div><div class="finale-flourish" aria-hidden="true"></div></section></div>`;finale.showModal();document.querySelector('#episode-replay').onclick=()=>{finale.close();restart()};document.querySelector('#episode-home').onclick=()=>{finale.close();closeReader()};}
const standardAdvance=advanceReading;
advanceReading=function(){if(active===1&&reader.open&&!readingMenu.open&&state.runs[1].step>=stories[1].scenes.length){if(!finale.open)showSummerFinale();return}standardAdvance()};
render();

finale.addEventListener('cancel',event=>{event.preventDefault();finale.close();closeReader()});
reader.addEventListener('close',()=>{if(finale.open)finale.close()});
